<script setup lang="ts">import { Link,useForm } from '@inertiajs/vue3';import { Plus,Trash2 } from '@lucide/vue';import { computed,watch } from 'vue';import { Button } from '@/components/ui/button';import { Input } from '@/components/ui/input';import { Label } from '@/components/ui/label';type Customer={id:string;name:string;default_price_list_id:string|null};type Item={id:string;presentation_id:string;product:string;price:number;minimum_price:number|null};type List={id:string;name:string;is_default:boolean;items:Item[]};type Option={value:string;label:string};type Order={customer_profile_id:string;price_list_id:string;ordered_at:string;due_at:string;priority:string;discount:number;notes:string|null;price_authorization_id:string|null;lines:any[]};const props=defineProps<{submitUrl:string;method:'post'|'put';customers:Customer[];priceLists:List[];priorities:Option[];now?:string;due?:string;order?:Order}>();const defaultList=props.priceLists.find(l=>l.is_default)?.id??props.priceLists[0]?.id??'';const form=useForm({customer_profile_id:props.order?.customer_profile_id??props.customers[0]?.id??'',price_list_id:props.order?.price_list_id??defaultList,ordered_at:props.order?.ordered_at??props.now??'',due_at:props.order?.due_at??props.due??'',priority:props.order?.priority??'normal',discount:props.order?.discount??0,notes:props.order?.notes??'',price_authorization_id:props.order?.price_authorization_id??'',confirm:false,lines:props.order?.lines.map(l=>({...l}))??[]});const list=computed(()=>props.priceLists.find(l=>l.id===form.price_list_id));const add=()=>{const item=list.value?.items[0];if(item)form.lines.push({presentation_id:item.presentation_id,quantity:1,unit_price:item.price,discount:0,price_reason:'',notes:''})};if(!form.lines.length)add();const priceItem=(id:string)=>list.value?.items.find(i=>i.presentation_id===id);const sync=(line:any)=>{const item=priceItem(line.presentation_id);line.unit_price=item?.price??0};watch(()=>form.customer_profile_id,(id)=>{const customer=props.customers.find(c=>c.id===id);if(customer?.default_price_list_id)form.price_list_id=customer.default_price_list_id});watch(()=>form.price_list_id,()=>form.lines.forEach(sync));const subtotal=computed(()=>form.lines.reduce((sum,l)=>sum+Math.max(0,Number(l.quantity||0)*Number(l.unit_price||0)-Number(l.discount||0)),0));const submit=(confirm:boolean)=>{form.confirm=confirm;props.method==='post'?form.post(props.submitUrl):form.put(props.submitUrl)};</script>
<template><form class="grid gap-6" @submit.prevent="submit(false)"><section class="grid gap-4 rounded-xl border bg-card p-5 md:grid-cols-3"><div class="grid gap-2"><Label>Cliente</Label><select v-model="form.customer_profile_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div class="grid gap-2"><Label>Lista de precios</Label><select v-model="form.price_list_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="l in priceLists" :key="l.id" :value="l.id">{{l.name}}</option></select></div><div class="grid gap-2"><Label>Prioridad</Label><select v-model="form.priority" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="p in priorities" :key="p.value" :value="p.value">{{p.label}}</option></select></div><div class="grid gap-2"><Label>Fecha del pedido</Label><Input v-model="form.ordered_at" type="datetime-local"/></div><div class="grid gap-2"><Label>Entrega</Label><Input v-model="form.due_at" type="datetime-local"/></div><div class="grid gap-2"><Label>Descuento general</Label><Input v-model.number="form.discount" type="number" min="0"/></div></section><section class="grid gap-3"><div class="flex justify-between"><div><h2 class="font-semibold">Productos</h2><p class="text-xs text-muted-foreground">Puedes cambiar el precio si tienes permiso; bajo el mínimo exige motivo y autorización.</p></div><Button type="button" variant="outline" size="sm" @click="add"><Plus/> Producto</Button></div><div v-for="(line,index) in form.lines" :key="index" class="grid items-end gap-3 rounded-lg border p-3 lg:grid-cols-[1fr_8rem_10rem_9rem_1fr_auto]"><div class="grid gap-2"><Label>Presentación</Label><select v-model="line.presentation_id" class="h-9 rounded-md border bg-transparent px-3 text-sm" @change="sync(line)"><option v-for="item in list?.items" :key="item.presentation_id" :value="item.presentation_id">{{item.product}}</option></select></div><div class="grid gap-2"><Label>Cantidad</Label><Input v-model.number="line.quantity" type="number" min="0.000001" step="0.000001"/></div><div class="grid gap-2"><Label>Precio</Label><Input v-model.number="line.unit_price" type="number" min="0"/><small class="text-muted-foreground">Lista {{priceItem(line.presentation_id)?.price||0}} · mín. {{priceItem(line.presentation_id)?.minimum_price||0}}</small></div><div class="grid gap-2"><Label>Descuento</Label><Input v-model.number="line.discount" type="number" min="0"/></div><div class="grid gap-2"><Label>Motivo del precio</Label><Input v-model="line.price_reason" placeholder="Si es personalizado"/></div><Button type="button" variant="ghost" size="icon" :disabled="form.lines.length===1" @click="form.lines.splice(index,1)"><Trash2/></Button></div></section><div class="grid gap-2"><Label>Notas</Label><textarea v-model="form.notes" rows="2" class="rounded-md border bg-transparent px-3 py-2 text-sm"/></div><div class="rounded-lg bg-muted/40 p-4 text-right"><p>Subtotal de líneas: <strong>${{subtotal.toLocaleString('es-CO')}}</strong></p><p>Total: <strong>${{Math.max(0,subtotal-Number(form.discount||0)).toLocaleString('es-CO')}}</strong></p></div><p v-if="Object.keys(form.errors).length" class="text-sm text-destructive">{{Object.values(form.errors)[0]}}</p><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link href="/orders">Cancelar</Link></Button><Button type="button" variant="outline" :disabled="form.processing" @click="submit(false)">Guardar borrador</Button><Button type="button" :disabled="form.processing" @click="submit(true)">Guardar y confirmar</Button></div></form></template>
